import heapq
from collections import defaultdict

def main():
    N, M = map(int, input().split())
    graph = [[] for _ in range(N)]
    for _ in range(M):
        l, d, k, c, a, b = map(int, input().split())
        a -= 1
        b -= 1
        graph[a].append((b, l, d, k, c))

    inf = float('inf')
    time = [-inf] * N
    time[0] = 0
    queue = [(0, 0)]

    while queue:
        tx, x = heapq.heappop(queue)
        tx = -tx  # Convert back to max-heap logic
        if time[x] > tx:
            continue
        for y, l, d, k, c in graph[x]:
            if tx < l:
                continue
            if l + (k - 1) * d <= tx - c:
                ty = l + (k - 1) * d
            else:
                ty = tx - ((tx - c - l) % d)
            if time[y] < ty:
                time[y] = ty
                heapq.heappush(queue, (-ty, y))

    for i in range(N - 1):
        ans = time[i]
        if ans == -inf:
            ans = "Unreachable"
        print(ans)
